// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    receive() external payable {}
    function testFuzz_property(uint256 amount) public {
        uint256 v = bound(amount, 0, type(uint240).max);
        // contract holds v + 1 wei so v is strictly less than the balance
        vm.deal(address(c), v + 1);
        vm.prank(address(this));
        c.withdraw(v);
        // Rule: after withdrawing v from a balance of v+1, exactly 1 wei remains.
        assertTrue(address(c).balance == 1, "withdraw(v) must leave balance - v");
    }
}
